pub fn fibonacci(n: u64) -> u64 {
    if n == 0 { return 0; }
    let mut a = 0u64;
    let mut b = 1u64;
    for _ in 1..n {
        let temp = a + b;
        a = b;
        b = temp;
    }
    a
}
